package ascii

import (
	"bufio"
	"image"
	"image/png"
	"log"
	"os"
	"testing"
)

// TODO share as util
func readImage(img_path string) (image.Image, error) {
	f, err := os.Open(img_path)

	if err != nil {
		log.Println("File not found")
		return nil, err
	}

	defer f.Close()

	reader := bufio.NewReader(f)

	img, err := png.Decode(reader)
	if err != nil {
		log.Println("Failed to read image")
		return nil, err
	}

	return img, nil
}

